/* ---------------- grid generator ---------------- */

const TEMPLATES = [
  ["#...#", ".....", ".....", ".....", "#...#"],
  ["...##", ".....", ".....", ".....", "##..."],
  ["##...", ".....", ".....", ".....", "...##"],
  [".....", ".....", "..#..", ".....", "....."],
  ["#....", ".....", ".....", ".....", "....#"],
  [".#..", "....", "....", "..#."],
  ["....", "....", "....", "...."],
  [".#..", "....", "....", "...."],
  ["....", "....", "....", "..#."],
];

function buildIndex(pack) {
  const idx = {};
  for (const L of Object.keys(pack)) {
    const n = +L, s = pack[L], count = s.length / n;
    const words = new Array(count);
    for (let i = 0; i < count; i++) words[i] = s.slice(i * n, (i + 1) * n);
    const nw = (count + 31) >> 5;
    const bits = new Uint32Array(n * 26 * nw);
    for (let i = 0; i < count; i++)
      for (let p = 0; p < n; p++) {
        const c = words[i].charCodeAt(p) - 65;
        bits[(p * 26 + c) * nw + (i >> 5)] |= 1 << (i & 31);
      }
    const all = new Uint32Array(nw).fill(0xffffffff);
    if (count & 31) all[nw - 1] = (1 << (count & 31)) - 1;
    idx[n] = { words, count, nw, bits, all };
  }
  return idx;
}
const IDX = buildIndex(LEX);

function slotsOf(grid) {
  const R = grid.length, C = grid[0].length, out = [];
  for (let r = 0; r < R; r++) {
    let c = 0;
    while (c < C) {
      if (grid[r][c] === "#") { c++; continue; }
      const s = c;
      while (c < C && grid[r][c] !== "#") c++;
      if (c - s >= 3) {
        const cs = [];
        for (let i = s; i < c; i++) cs.push([r, i]);
        out.push({ dir: "A", cells: cs });
      }
    }
  }
  for (let c = 0; c < C; c++) {
    let r = 0;
    while (r < R) {
      if (grid[r][c] === "#") { r++; continue; }
      const s = r;
      while (r < R && grid[r][c] !== "#") r++;
      if (r - s >= 3) {
        const cs = [];
        for (let i = s; i < r; i++) cs.push([i, c]);
        out.push({ dir: "D", cells: cs });
      }
    }
  }
  return out;
}

// Backtracking fill with a most-constrained-slot heuristic and a
// frequency bias so early levels use commoner words.
// Only the commonest `capFrac` of each word length is allowed into the grid.
// This is the main difficulty lever: early grids never see obscure fill.
function capMask(D, capFrac) {
  const cap = Math.min(D.count, Math.max(80, Math.ceil(D.count * capFrac)));
  const m = Uint32Array.from(D.all);
  for (let i = cap; i < D.count; i++) m[i >> 5] &= ~(1 << (i & 31));
  // Roman numerals rank as common but feel like a trick to a new player;
  // keep them out until the pool has opened up.
  if (capFrac < 0.6)
    for (let i = 0; i < cap; i++) if (/^[IVX]+$/.test(D.words[i])) m[i >> 5] &= ~(1 << (i & 31));
  return m;
}

function fillGrid(template, bias, capFrac = 1, opts = {}) {
  const rng = opts.rng || Math.random;
  const slots = slotsOf(template);
  const caps = {};
  for (const n of Object.keys(IDX)) {
    caps[n] = capMask(IDX[n], capFrac);
    if (opts.mask && opts.mask[n]) for (let k = 0; k < caps[n].length; k++) caps[n][k] &= opts.mask[n][k];
  }
  const cells = new Map();
  const assigned = new Array(slots.length).fill(null);
  const used = new Set();
  const key = (r, c) => r * 16 + c;
  let steps = 0;

  const candidates = (i) => {
    const cs = slots[i].cells, n = cs.length, D = IDX[n];
    const acc = Uint32Array.from(caps[n]);
    for (let p = 0; p < n; p++) {
      const ch = cells.get(key(cs[p][0], cs[p][1]));
      if (!ch) continue;
      const off = (p * 26 + (ch.charCodeAt(0) - 65)) * D.nw;
      for (let k = 0; k < D.nw; k++) acc[k] &= D.bits[off + k];
    }
    const res = [];
    for (let k = 0; k < D.nw; k++) {
      let v = acc[k];
      while (v) {
        const b = v & -v;
        const wi = (k << 5) + (31 - Math.clz32(b));
        const w = D.words[wi];
        if (!used.has(w)) res.push(w);
        v ^= b;
      }
    }
    return res;
  };

  const order = slots.map((_, i) => i);
  function search(k) {
    if (++steps > 60000) throw new Error("budget");
    if (k === order.length) return true;
    let bestAt = -1, best = null;
    for (let t = k; t < order.length; t++) {
      const l = candidates(order[t]);
      if (best === null || l.length < best.length) { bestAt = t; best = l; }
      if (l.length === 0) break;
    }
    if (best.length === 0) return false;
    [order[k], order[bestAt]] = [order[bestAt], order[k]];
    const i = order[k], cs = slots[i].cells;
    // pick in rank order but weighted toward common words
    const pool = best.slice(), tries = [];
    while (pool.length && tries.length < 25)
      tries.push(pool.splice(Math.floor(Math.pow(rng(), bias) * pool.length), 1)[0]);
    for (const w of tries) {
      const prev = cs.map(([r, c]) => cells.get(key(r, c)));
      cs.forEach(([r, c], p) => cells.set(key(r, c), w[p]));
      used.add(w); assigned[i] = w;
      if (search(k + 1)) return true;
      used.delete(w); assigned[i] = null;
      cs.forEach(([r, c], p) => {
        const kk = key(r, c);
        if (prev[p] === undefined) cells.delete(kk); else cells.set(kk, prev[p]);
      });
    }
    return false;
  }
  try { if (!search(0)) return null; } catch (e) { return null; }
  return { slots, words: assigned, template };
}

/* ---------------- difficulty ---------------- */

// Tiers set the grid shapes and clue style; within a tier the word pool and
// the frequency bias still ramp level by level, so no two levels feel the same
// and the climb is monotonic rather than random.
// `clueTier` indexes the bundle's clue tiers (plain / standard / oblique).
const TIERS = [
  { label: "Easy", upTo: 2, templates: [5, 7, 8], clueTier: 0, clues: "plain dictionary-style definitions" },
  { label: "Medium", upTo: 5, templates: [5, 6, 7, 8], clueTier: 0, clues: "plain, direct crossword clues" },
  { label: "Hard", upTo: 9, templates: [3, 0, 1, 2, 4], clueTier: 1, clues: "concise crossword clues, a little indirect" },
  { label: "Expert", upTo: Infinity, templates: [0, 1, 2, 3, 4], clueTier: 2, clues: "wry, oblique crossword clues with light wordplay" },
];
const tierFor = (level) => TIERS.find((t) => level <= t.upTo);
// share of the lexicon in play: 35% at level 1, everything from level 10 on
const capFor = (level) => Math.min(1, 0.35 + 0.08 * (level - 1));
// how strongly the fill leans toward common words: 3.5 at level 1, floor of 1.2
const biasFor = (level) => Math.max(1.2, 3.5 - 0.3 * (level - 1));

function makePuzzle(level, opts = {}) {
  const rng = opts.rng || Math.random;
  const tier = tierFor(level);
  const bias = biasFor(level);
  // a tight cap can make a template unfillable; loosen it a little per attempt
  for (let attempt = 0; attempt < 12; attempt++) {
    const cap = Math.min(1, capFor(level) + 0.05 * attempt);
    const t = TEMPLATES[tier.templates[Math.floor(rng() * tier.templates.length)]];
    const r = fillGrid(t, bias, cap, opts);
    if (r) return buildPuzzle(r);
  }
  for (let attempt = 0; attempt < 40; attempt++) {
    const r = fillGrid(TEMPLATES[5], 2, 1, opts);
    if (r) return buildPuzzle(r);
  }
  return null;
}

function buildPuzzle(f) {
  const g = f.template;
  const R = g.length, C = g[0].length;
  const solution = Array.from({ length: R }, (_, r) =>
    Array.from({ length: C }, (_, c) => (g[r][c] === "#" ? null : ""))
  );
  f.slots.forEach((s, i) => s.cells.forEach(([r, c], p) => (solution[r][c] = f.words[i][p])));
  // standard numbering
  const num = Array.from({ length: R }, () => Array(C).fill(0));
  let n = 1;
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++) {
      if (g[r][c] === "#") continue;
      const startA = (c === 0 || g[r][c - 1] === "#") && c + 2 < C && g[r][c + 1] !== "#" && g[r][c + 2] !== "#";
      const startD = (r === 0 || g[r - 1][c] === "#") && r + 2 < R && g[r + 1][c] !== "#" && g[r + 2][c] !== "#";
      if (startA || startD) num[r][c] = n++;
    }
  const entries = f.slots.map((s, i) => ({
    id: i,
    dir: s.dir,
    cells: s.cells,
    word: f.words[i],
    number: num[s.cells[0][0]][s.cells[0][1]],
    clue: null,
  }));
  entries.sort((a, b) => a.number - b.number || (a.dir === "A" ? -1 : 1));
  return { rows: R, cols: C, blocks: g, solution, numbers: num, entries };
}

/* ---------------- pre-verified bundle ---------------- */

// A bundle from generate-puzzles.mjs carries puzzles whose every clue has
// passed the blind-solve check. When one is reachable it is the source of
// truth; live generation below is the fallback (and what the claude.ai
// artifact sandbox uses, since it has no bundle file).
// Words that must never reach a player. They are gone from lexicon.json, but
// an older bundle may still carry them, so puzzles using one are skipped.
const BLOCKED = new Set("NEGRO NIGGA CHINK COON HOMO CUNT RAPED JIHAD SLAVE GYPSY SQUAW GIMP NIP".split(" "));

// A host can hand the bundle over directly instead of serving it (the Expo
// wrapper imports it into the page); otherwise it is fetched from next door.
const bundleReady = (typeof window !== "undefined" && window.CROSSRUN_BUNDLE
  ? Promise.resolve(window.CROSSRUN_BUNDLE)
  : typeof fetch === "function"
  ? fetch("bundle.json").then((r) => (r.ok ? r.json() : null)).catch(() => null)
  : Promise.resolve(null)
).then((b) => {
  if (!b || !b.puzzles || !b.clues) return null;
  const counts = {};
  for (const L of Object.keys(b.lexicon)) counts[L] = b.lexicon[L].length / +L;
  b.puzzles.forEach((p) => {
    const tpl = b.templates[p.t];
    const slots = slotsOf(tpl);
    p.words = slots.map((s, i) => {
      const n = s.cells.length;
      return b.lexicon[n].slice(p.w[i] * n, (p.w[i] + 1) * n);
    });
    p.maxRank = Math.max(...slots.map((s, i) => p.w[i] / counts[s.cells.length]));
    p.roman = p.words.some((w) => /^[IVX]+$/.test(w));
    p.clued = p.words.every((w) => b.clues[w] && !BLOCKED.has(w));
    p.sig = p.t + ":" + p.w.join(","); // stable identity across bundle rebuilds
  });
  // Which of the game's own words carry verified clues: the filler draws fresh
  // grids from exactly these, so every level is new and every clue is checked.
  b.cluedMask = {};
  let cluedCount = 0;
  for (const n of Object.keys(IDX)) {
    const D = IDX[n], m = new Uint32Array(D.nw);
    for (let i = 0; i < D.count; i++) if (b.clues[D.words[i]] && !BLOCKED.has(D.words[i])) { m[i >> 5] |= 1 << (i & 31); cluedCount++; }
    b.cluedMask[n] = m;
  }
  b.cluedCount = cluedCount;
  return b;
});

// Puzzles already played are remembered (and saved) so they come back only
// once everything else at that difficulty has been used.
const seenBundle = new Set();

// Small seeded generator for the daily run: everyone gets the same sequence.
const mulberry32 = (a) => () => {
  a |= 0; a = (a + 0x6d2b79f5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const hashStr = (str) => { let h = 2166136261; for (const c of str) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const todayKey = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };

function pickFromBundle(b, level, opts = {}) {
  if (!b) return null;
  const rng = opts.rng || Math.random;
  const skip = opts.ignoreSeen ? new Set() : seenBundle;
  const tier = tierFor(level);
  const tset = new Set(tier.templates);
  const roman = capFor(level) < 0.6;
  // first pass avoids puzzles already played; second pass allows them
  for (const avoidSeen of [true, false]) {
    for (let cap = capFor(level); cap <= 1.5; cap += 0.1) {
      const pool = [];
      b.puzzles.forEach((p) => {
        if (p.clued && tset.has(p.t) && p.maxRank <= cap && !(roman && p.roman) && !(avoidSeen && skip.has(p.sig))) pool.push(p);
      });
      if (pool.length >= 5 || (cap > 1 && pool.length)) {
        const p = pool[Math.floor(rng() * pool.length)];
        if (!opts.ignoreSeen) seenBundle.add(p.sig);
        const tpl = b.templates[p.t];
        const puzzle = buildPuzzle({ slots: slotsOf(tpl), words: p.words, template: tpl });
        puzzle.entries.forEach((e) => (e.clue = b.clues[e.word][tier.clueTier]));
        puzzle.source = "bundle";
        return puzzle;
      }
    }
  }
  return null;
}

// One entry point for a level. Preferred: fill a brand-new grid on the device
// from the words that have verified clues (seeded for the daily run), and
// attach the clue tier for the level. Fallbacks: a pre-built bundle puzzle,
// then live generation.
async function buildLevel(level, opts = {}) {
  const b = await bundleReady;
  if (b && b.cluedCount > 300) {
    const p = makePuzzle(level, { rng: opts.rng, mask: b.cluedMask });
    if (p) {
      const tier = tierFor(level);
      p.entries.forEach((e) => (e.clue = b.clues[e.word][tier.clueTier]));
      p.source = "fresh";
      return p;
    }
  }
  const fromBundle = pickFromBundle(b, level, opts);
  if (fromBundle) return fromBundle;
  const p = makePuzzle(level) || makePuzzle(1);
  p.source = "live";
  return attachClues(p, level);
}

// Haptics come from the native shell when there is one; harmless elsewhere.
const haptic = (kind) => { try { if (typeof window !== "undefined" && window.CROSSRUN_HAPTIC) window.CROSSRUN_HAPTIC(kind); } catch (e) {} };

/* ---------------- clue writing (Claude) ---------------- */

async function writeClues(words, level) {
  const style = tierFor(level).clues;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 1000,
      messages: [
        {
          role: "user",
          content:
            `Write one crossword clue for each word below. Style: ${style}. ` +
            `Rules: at most 7 words per clue; never use the answer word or any form of it; no enumerations.\n` +
            `Words: ${words.join(", ")}\n\n` +
            `Reply with JSON only, no prose, no code fences: an object mapping each uppercase word to its clue.`,
        },
      ],
    }),
  });
  const data = await res.json();
  if (!res.ok || data.error) throw new Error(data.error ? data.error.message : `http ${res.status}`);
  const text = data.content.map((b) => (b.type === "text" ? b.text : "")).join("");
  const t = text.replace(/```json|```/g, "").trim();
  const start = t.indexOf("{"), end = t.lastIndexOf("}");
  if (start === -1 || end <= start) throw new Error("no JSON object in reply");
  return JSON.parse(t.slice(start, end + 1));
}

// A clue is unusable if it leaks the answer. Compare whole words, not
// substrings: "Loneliest number" is a fine clue for ONE, and a THEN clue that
// contains "the" is not a leak. Inflections of the answer (BAKER / bakes,
// USED / use, CATS / cat) are still caught. Suffixes are only stripped where
// they are a real inflection, so FORD does not get the root "for" and THEY
// does not get "the".
function leaksAnswer(clue, word) {
  const w = word.toLowerCase();
  const roots = new Set([w]);
  const addRoot = (r) => {
    roots.add(r);
    if (!r.endsWith("e")) roots.add(r + "e");                                   // baker -> bake
    if (r.length > 3 && r[r.length - 1] === r[r.length - 2]) roots.add(r.slice(0, -1)); // running -> run
  };
  const strip = (suf) => (w.endsWith(suf) ? w.slice(0, -suf.length) : null);
  let r;
  if ((r = strip("s")) && r.length >= 3) addRoot(r);
  if ((r = strip("es")) && r.length >= 3 && /(s|x|z|ch|sh)$/.test(r)) addRoot(r);
  if ((r = strip("d")) && r.length >= 3 && r.endsWith("e")) addRoot(r);      // used -> use
  for (const suf of ["ed", "er", "ers", "ing"]) if ((r = strip(suf)) && r.length >= 3) addRoot(r);
  for (const suf of ["ly", "y"]) if ((r = strip(suf)) && r.length >= 4) addRoot(r); // windy -> wind, not they -> the
  for (const suf of ["ies", "ied", "ier", "iest"]) if ((r = strip(suf)) && r.length >= 2) roots.add(r + "y"); // tries -> try
  const forms = new Set();
  for (const r of roots) {
    forms.add(r);
    forms.add(r + (/(s|x|z|ch|sh)$/.test(r) ? "es" : "s"));
    if (r.endsWith("e")) for (const suf of ["d", "r", "rs"]) forms.add(r + suf);
    const stem = r.endsWith("e") ? r.slice(0, -1) : r;
    for (const suf of ["ed", "er", "ers", "ing"]) forms.add(stem + suf);
    if (/[^aeiouwxy]$/.test(r) && /[aeiou][^aeiou]$/.test(r))                   // run -> running, sun -> sunny
      for (const suf of ["ed", "er", "ers", "ing", "y"]) forms.add(r + r[r.length - 1] + suf);
    if (r.endsWith("y")) for (const suf of ["ies", "ied", "ier", "iest"]) forms.add(r.slice(0, -1) + suf);
    else if (r.length >= 4) { forms.add(r + "y"); forms.add(r + "ly"); }
  }
  const tokens = clue.toLowerCase().match(/[a-z]+/g) || [];
  return tokens.some((t) => forms.has(t));
}

function fallbackClue(w) {
  return FALLBACK_CLUES[w] || `${w.length} letters, starts with ${w[0]}`;
}

// Live clue writing needs a proxy that holds the API key (the dev server or the
// claude.ai sandbox). The packaged app has none, so it goes straight to fallbacks.
const LIVE_CLUES =
  typeof window !== "undefined" &&
  Boolean(window.CROSSRUN_LIVE_CLUES || /claude\.ai$/.test((window.location && window.location.hostname) || ""));

async function attachClues(puzzle, level) {
  const words = puzzle.entries.map((e) => e.word);
  let map = {};
  try {
    if (LIVE_CLUES) map = await writeClues(words, level);
  } catch (e) {
    map = {};
  }
  puzzle.entries.forEach((e) => {
    const c = map[e.word] || map[e.word.toLowerCase()];
    const ok = typeof c === "string" && c.trim() && !leaksAnswer(c, e.word);
    e.clue = ok ? c.trim() : fallbackClue(e.word);
  });
  return puzzle;
}

