/* ---------------- ambience ----------------
 * Lanterns, lamplight, drifting motes or fireflies, and a branch at the
 * edge. All CSS, all slow, all behind or softly over the content. */
const MOTES = Array.from({ length: 10 }, (_, i) => {
  const r = mulberry32(1234 + i);
  return { left: 3 + r() * 94, top: 8 + r() * 84, size: 3 + r() * 4, dur: 9 + r() * 10, delay: -r() * 14, drift: 20 + r() * 40 };
});
// A vine drawn as SVG: a curving stem with leaves clustered along it, so it
// reads as one plant rather than scattered leaves. `swag` drapes across the
// top; `tendril` trails down a side.
const bez = (p0, p1, p2, p3, t) => {
  const u = 1 - t;
  return [u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
          u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1]];
};
const GREENS = ["#5E7A55", "#6B8261", "#7E9473", "#8FA57F"];
function Vine({ kind = "swag", side = "left", width = 430, seed = 7, className = "" }) {
  const r = mulberry32(seed);
  const W = width, H = kind === "swag" ? 96 : 240;
  const P = kind === "swag"
    ? [[-10, 18], [W * 0.3, 118], [W * 0.7, 118], [W + 10, 18]]
    : side === "left" ? [[14, -10], [40, 80], [-6, 150], [26, H]] : [[W - 14, -10], [W - 40, 80], [W + 6, 150], [W - 26, H]];
  const stem = `M${P[0][0]},${P[0][1]} C${P[1][0]},${P[1][1]} ${P[2][0]},${P[2][1]} ${P[3][0]},${P[3][1]}`;
  const leaves = [];
  const n = kind === "swag" ? 16 : 9;
  for (let i = 1; i < n; i++) {
    const t = i / n;
    const [x, y] = bez(P[0], P[1], P[2], P[3], t);
    const [x2, y2] = bez(P[0], P[1], P[2], P[3], t + 0.01);
    const tangent = (Math.atan2(y2 - y, x2 - x) * 180) / Math.PI;
    const count = 2 + (r() < 0.5 ? 1 : 0);
    for (let k = 0; k < count; k++) {
      const sideSign = (i + k) % 2 ? 1 : -1;
      const ang = tangent + sideSign * (55 + r() * 30) + (r() - 0.5) * 20;
      const len = 20 + r() * 12, wid = 8 + r() * 5;
      leaves.push({ x, y, ang, len, wid, fill: GREENS[Math.floor(r() * GREENS.length)] });
    }
  }
  return (
    <svg className={"vine " + kind + " " + side + " " + className} viewBox={`0 0 ${W} ${H}`} width={W} height={H} aria-hidden="true">
      <path d={stem} fill="none" stroke={ART.ink} strokeWidth="5" strokeLinecap="round" />
      <path d={stem} fill="none" stroke="#5E7A55" strokeWidth="2.2" strokeLinecap="round" />
      {leaves.map((l, i) => (
        <g key={i} transform={`translate(${l.x},${l.y}) rotate(${l.ang})`}>
          <path d={`M0,0 Q${l.len * 0.5},${-l.wid} ${l.len},0 Q${l.len * 0.5},${l.wid} 0,0 Z`} fill={l.fill} stroke={ART.ink} strokeWidth="1.8" strokeLinejoin="round" />
          <path d={`M3,0 L${l.len - 4},0`} stroke={ART.ink} strokeWidth="1" opacity=".5" />
        </g>
      ))}
    </svg>
  );
}

